/* Builder: explicit per-crop core + shared category agronomy => full spec-shaped object */
var _n = 0;
function C(id,name,sci,cat,temp,days,dur,season,soil,ph,water,rain,regions,seed,desc,pk,pnote,dk,dnote,harvest,imgkw){
  _n++;
  /* Normalize legacy rows that omitted the disease-index array. */
  if (!Array.isArray(dk)) {
    imgkw = harvest;
    harvest = dnote;
    dnote = dk;
    dk = [0,1];
  }
  var T = POOL[cat];
  function P(k,note){ var e = T.pests[k]; return {name:e[0], symptoms:e[1]+(note?" "+note:""), prevention:e[2], monitoring:"Inspect the crop weekly from early growth; refresh pheromone and sticky traps.", management:e[2]+"; remove and destroy badly affected parts; use approved controls only as per local agricultural advisory."}; }
  function D(k,note){ var e = T.diseases[k]; return {name:e[0], symptoms:e[1]+(note?" "+note:""), cause:e[2], prevention:e[3], management:"Rogue infected plants, improve drainage and airflow; apply bio-agents first and chemicals only on local advisory."}; }
  var pests = [P(pk[0],pnote), P(pk[1],"")];
  var diseases = [D(dk[0],dnote), D(dk[1],"")];
  var vline = "Recommendation varies by region and variety. Verify with the local agricultural department or approved agricultural advisory.";
  return { id:id, name:name, scientificName:sci, category:cat,
    image:"https://loremflickr.com/600/400/"+imgkw+"?lock="+_n,
    shortDescription:desc, temperature:temp, duration:dur, days:days, season:season,
    soil:soil+" (pH "+ph+")", waterRequirement:water,
    climate:temp+", "+season+" season", rainfall:rain, majorRegions:regions,
    varieties:["Location-specific improved types. "+vline],
    seedRate:"Certified seed at the locally advised rate for the chosen variety. "+vline,
    sowing:seed+" Sow in the "+season+" window ("+dur+" crop).", spacing:T.spacing,
    landPreparation:T.landPrep.slice(),
    nutrientManagement:T.nutrients.concat(["Apply nutrients according to soil-test results and locally recommended crop guidelines."]),
    irrigation:["Water need: "+water+"."].concat(T.irrig),
    weedManagement:T.weed.slice(), pests:pests, diseases:diseases,
    growthStages:T.stages.map(function(s){return {stage:s[0], detail:s[1]};}),
    harvesting:["Maturity signs: "+harvest,"Timing: toward the end of the "+dur+" cycle; harvest in dry morning hours.","Method: sharp clean tools; variety-typical cutting or picking.","Handling: shade-collect, avoid bruising and wet heaps."],
    postHarvest:T.post.slice(), storage:T.storage.slice(),
    marketInformation:name+": "+T.market,
    precautions:T.precautions.concat([vline]) };
}
